    /// Scope: read. Since: 1.0.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/ticks/{symbol}{?day,from,limit}
    /// </summary>
    /// <param name="day">The day, YYYY-MM-DD; omitted, the day at the workbench's cursor.</param>
    /// <param name="from">Ticks from this index of the day on.</param>
    /// <param name="limit">How many, at most 20000.</param>
    public Task<JsonNode?> Ticks(string home, string owner, string bench, string symbol, string? day = null, long? from = null, long? limit = null, CancellationToken ct = default) =>
        _c.ReadResource("bentrix://{home}/{owner}/bench/{bench}/ticks/{symbol}{?day,from,limit}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["symbol"] = symbol, ["day"] = day, ["from"] = from, ["limit"] = limit }, ct);

    /// <summary>Every page of <see cref="Ticks"/>, following <c>next</c> until it is absent.</summary>
    public IAsyncEnumerable<JsonNode?> TicksPages(string home, string owner, string bench, string symbol, string? day = null, long? from = null, long? limit = null, CancellationToken ct = default) =>
        _c.ReadPages("bentrix://{home}/{owner}/bench/{bench}/ticks/{symbol}{?day,from,limit}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["symbol"] = symbol, ["day"] = day, ["from"] = from, ["limit"] = limit }, ct);

    /// <summary>
    /// Each bar of one market and interval that closed after the cursor, oldest first, never the one still forming, at most 2000 a page; next is the last closed bar's open time (UTC ms). Omitted after answers no bar and next at the newest closed bar, so a reader starts at the present. rewound is true when the workbench's clock went back behind after (a laboratory's rewind): next is then the newest bar closed now, and the bars after it close again.
    /// Scope: read. Since: 1.3.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/bars/{symbol}/{tf}/closed{?after}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> ClosedBars(string home, string owner, string bench, string symbol, string tf, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/bars/{symbol}/{tf}/closed{?after}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["symbol"] = symbol, ["tf"] = tf }, after, timeoutMs, ct);

    /// <summary>
    /// Each element of a chart built by price or activity (Renko, Range bars, Line break, Point &amp; Figure, Kagi, Volume bars) that closed after the cursor, oldest first, as chart_elements_get reads it (its candle's open and ordinal, open, high, low, close, volume), never the one forming. The cursor is time:ordinal; omitted after answers none and next at the newest closed element. rewound is true when the chart's newest closed element stands behind the cursor (the clock went back, or the chart was rebuilt).
    /// Scope: read. Since: 3.3.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/chart/{chart}/elements/closed{?after}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> ClosedElements(string home, string owner, string bench, string chart, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/chart/{chart}/elements/closed{?after}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["chart"] = chart }, after, timeoutMs, ct);

    /// <summary>
    /// Each bar of one market and interval (tf) that closed after the cursor, oldest first, at most 8 a page, each with a bars_window aligned to that close: the frames (comma-separated intervals; tf alone when omitted) of the markets (comma-separated; symbol alone when omitted), every frame cut where that bar ended, limit rows each (200, at most 5000). A model reading it runs exactly once per close. next is the last bar's open time (UTC ms); omitted after answers no window and next at the newest closed bar. rewound is true when the workbench's clock went back behind after.
    /// Scope: read. Since: 3.3.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/bars/{symbol}/{tf}/closed/window{?after,frames,symbols,limit}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    /// <param name="frames">The frames, comma-separated intervals: M15,H1,H4. Omitted, tf alone.</param>
    /// <param name="limit">Closed bars per frame per market in each window (200 when omitted, at most 5000).</param>
    /// <param name="symbols">The markets, comma-separated: EURUSD,GBPUSD. Omitted, symbol alone.</param>
    public IAsyncEnumerable<JsonNode?> ClosedWindow(string home, string owner, string bench, string symbol, string tf, string? frames = null, string? limit = null, string? symbols = null, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/bars/{symbol}/{tf}/closed/window{?after,frames,symbols,limit}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["symbol"] = symbol, ["tf"] = tf, ["frames"] = frames, ["limit"] = limit, ["symbols"] = symbols }, after, timeoutMs, ct);

    /// <summary>
    /// Each element of a chart built by price that closed after the cursor (time:ordinal), at most 8 a page, with a bars_window beside it: the chart's own closed elements up to and with it, and the interval frames of its market (comma-separated) cut at the open of the candle the element formed in - the last instant every one of their bars had certainly closed before the element did. rewound as data_closed_elements says it.
    /// Scope: read. Since: 3.3.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/chart/{chart}/elements/window{?after,frames,limit}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    /// <param name="frames">The interval frames beside the chart's own elements, comma-separated: M15,H1. Omitted, the elements alone.</param>
    /// <param name="limit">Rows per frame in each window (200 when omitted, at most 5000).</param>
    public IAsyncEnumerable<JsonNode?> ElementsWindow(string home, string owner, string bench, string chart, string? frames = null, string? limit = null, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/chart/{chart}/elements/window{?after,frames,limit}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["chart"] = chart, ["frames"] = frames, ["limit"] = limit }, after, timeoutMs, ct);

    /// <summary>
    /// Each bar of one market and interval from the cursor's open time on, oldest first, at most 2000 a page, the forming one last and said so; the bar at after is answered again, since it may have been forming. next is the last bar's open time. rewound is true when the workbench's clock went back behind after: next is then the bar forming now.
    /// Scope: read. Since: 1.0.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/bars/{symbol}/{tf}/live{?after}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> LiveBars(string home, string owner, string bench, string symbol, string tf, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/bars/{symbol}/{tf}/live{?after}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["symbol"] = symbol, ["tf"] = tf }, after, timeoutMs, ct);

    /// <summary>
    /// Each tick of one market as the workbench's clock passes it, oldest first, at most 20000 a page; next is the cursor (day:index). A cursor on an earlier day reads the rest of that day first, then each later day held, so a reader across midnight loses none. Omitted after starts at the cursor's present. rewound is true when the workbench's clock went back behind after (a laboratory's rewind): next is then the clock's present, and the ticks after it come again.
    /// Scope: read. Since: 1.0.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/ticks/{symbol}/live{?after}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> LiveTicks(string home, string owner, string bench, string symbol, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/ticks/{symbol}/live{?after}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["symbol"] = symbol }, after, timeoutMs, ct);

    /// <summary>
    /// The newest bid and ask of each of the workbench's markets, with the instant it was quoted and its digits, each time one moves at the workbench's clock; next is the newest instant read (UTC ms).
    /// Scope: read. Since: 1.0.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/quotes{?after}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> Quotes(string home, string owner, string bench, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/quotes{?after}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench }, after, timeoutMs, ct);
}

