public sealed class ForecastApi
{
    private readonly Client _c;

    internal ForecastApi(Client c) => _c = c;

    /// <summary>
    /// Sets how a chart draws a model's forecast: show, the ghost's opacity, uncertainty (fan, band, paths, off), the bands' opacity, the room on the right (forecast, shift_only, or N slots), how long a realized forecast stays (until_replaced, off, {horizons}, {bars}), a coarser interval spanned or by time, a finer one folded or by time, an element forecast on a time chart (auto, strip, by_expected_time, panel), a time forecast and another rule on a chart built by price (derived, strip, both), a profile (forecast_session, strip, off), true equivolume's widths (by_volume, median), the time past the newest bar (clock_time, session_time), the sampled paths drawn, and the models hidden on it (the legend's eye); models_per_market applies to every workbench. A field not named keeps its value. Answers the chart's forecast settings.
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    /// <param name="chart">The chart's uri.</param>
    /// <param name="arrivalMarks">A tick on the time axis at each forecast's arrival.</param>
    /// <param name="bandOpacity">The bands' opacity, 0.05 to 0.6.</param>
    /// <param name="coarser">A coarser interval: "spanned" or "by_time".</param>
    /// <param name="diff">**The diff view**: {"a": model, "b": model} shades the gap between their closes step by step; "off" takes it away.</param>
    /// <param name="elementOnTime">An element forecast (renko, kagi, …) on a time chart: "auto" (by expected time where every step says when it closes, else the strip), "strip", "by_expected_time" or "panel".</param>
    /// <param name="equivolumeWidth">A step's width on true equivolume: "by_volume" (its own volume, else the window's median) or "median".</param>
    /// <param name="finer">A finer interval: "folded" or "by_time".</param>
    /// <param name="hidden">Models hidden on this chart, as the legend's eye hides them: the whole set.</param>
    /// <param name="journal">The journal, for every workbench: laboratory_and_paper (the default), also_real, or off.</param>
    /// <param name="keepAfterRealized">Keep after realized: "until_replaced", "off", {"horizons": n} or {"bars": n}.</param>
    /// <param name="modelsPerMarket">Models per market, for every workbench: 1 to 64.</param>
    /// <param name="onProfile">On a profile: "forecast_session" (letters over the rows one session after the last), "strip" or "off".</param>
    /// <param name="opacity">The ghost's opacity, 0.2 to 1.</param>
    /// <param name="otherRule">An element forecast of another type or rule on a chart built by price: "derived", "strip" or "both".</param>
    /// <param name="pastNewest">Past the newest bar: "clock_time", or "session_time" (only the hours the market prints bars in).</param>
    /// <param name="readAtAnchor">Read a forecast at its anchor, for every workbench: {"laboratory": bool, "paper_and_real": bool}; both off by default. A look-ahead: marked wherever it reads; on a live bench never the newest close.</param>
    /// <param name="readout">A step's figures beside the pointer and in the data window.</param>
    /// <param name="room">Room on the right: "forecast" (as wide as the widest forecast), "shift_only", or a number of slots.</param>
    /// <param name="samplesDrawn">Sampled paths drawn per step, 1 to 256.</param>
    /// <param name="show">Draw forecasts on this chart.</param>
    /// <param name="timeOnElements">A time forecast on a chart built by price: "derived" (through the chart's own rule), "strip" or "both".</param>
    /// <param name="trail">The trail: the forecasts each model put before the one standing, drawn faint - 0 (off) to 64.</param>
    /// <param name="uncertainty">fan, band, paths or off.</param>
    public Task<JsonNode?> ChartSetForecast(string chart, bool? arrivalMarks = null, double? bandOpacity = null, string? coarser = null, object? diff = null, string? elementOnTime = null, string? equivolumeWidth = null, string? finer = null, IReadOnlyList<string>? hidden = null, string? journal = null, object? keepAfterRealized = null, long? modelsPerMarket = null, string? onProfile = null, double? opacity = null, string? otherRule = null, string? pastNewest = null, object? readAtAnchor = null, bool? readout = null, object? room = null, long? samplesDrawn = null, bool? show = null, string? timeOnElements = null, long? trail = null, string? uncertainty = null, CancellationToken ct = default) =>
        _c.Call("chart_set_forecast", new Dictionary<string, object?> { ["chart"] = chart, ["arrival_marks"] = arrivalMarks, ["band_opacity"] = bandOpacity, ["coarser"] = coarser, ["diff"] = diff, ["element_on_time"] = elementOnTime, ["equivolume_width"] = equivolumeWidth, ["finer"] = finer, ["hidden"] = hidden, ["journal"] = journal, ["keep_after_realized"] = keepAfterRealized, ["models_per_market"] = modelsPerMarket, ["on_profile"] = onProfile, ["opacity"] = opacity, ["other_rule"] = otherRule, ["past_newest"] = pastNewest, ["read_at_anchor"] = readAtAnchor, ["readout"] = readout, ["room"] = room, ["samples_drawn"] = samplesDrawn, ["show"] = show, ["time_on_elements"] = timeOnElements, ["trail"] = trail, ["uncertainty"] = uncertainty }, ct);

    /// <summary>
    /// Removes the forecasts of one model, one market, or all of them from the workbench, every arrival kept for them included, as the × on a forecast's legend row does. Answers how many (market, model) pairs were cleared.
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="model">One model; omitted, every model.</param>
    /// <param name="symbol">One market; omitted, every market.</param>
    public Task<JsonNode?> Clear(string bench, string? model = null, string? symbol = null, CancellationToken ct = default) =>
        _c.Call("forecast_clear", new Dictionary<string, object?> { ["bench"] = bench, ["model"] = model, ["symbol"] = symbol }, ct);

    /// <summary>
    /// forecast_report for several models on one market, a row each, over the same journal and the same bars. Unordered (by name) unless metric_order names a measure, then best first. A comparison is a laboratory's instrument: nothing here is published or ranked anywhere else.
    /// Scope: read. Since: 3.3.0.
    /// </summary>
    /// <param name="metricOrder">Order the rows by this measure, best first (mae_close, rmse_close, mape_close, pinball_loss, crps ascending; direction_hit_rate descending). Omitted, by the model's name: no ranking is drawn unless asked.</param>
    /// <param name="models">The models; omitted, every model the journal holds on the market.</param>
    public Task<JsonNode?> Compare(string bench, string symbol, long? last = null, string? metricOrder = null, IReadOnlyList<string>? models = null, CancellationToken ct = default) =>
        _c.Call("forecast_compare", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["last"] = last, ["metric_order"] = metricOrder, ["models"] = models }, ct);

    /// <summary>
    /// The two models' forecasts a reader at the workbench's clock sees on one market, step by step where their steps open at the same instant: each one's close and the difference (b minus a), and where their outermost bands overlap.
    /// Scope: read. Since: 3.3.0.
    /// </summary>
    public Task<JsonNode?> Diff(string bench, string symbol, string a, string b, CancellationToken ct = default) =>
        _c.Call("forecast_diff", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["a"] = a, ["b"] = b }, ct);

    /// <summary>
    /// Declares an ensemble on a workbench's market: its label, its members (models' labels), the rule its closes are combined by (mean, median, weighted with one weight a member) and the NAMED rule its bands are combined by - quantiles_averaged (each level's lo and hi averaged; the band claims no coverage of its own), members_pooled (the mixture of the members' samples, quantiles or band edges, its quantiles at each level; partly pooled where a member gave only a band), or none. Bentrix computes only what is declared: whenever a member's newest forecast arrives and every member stands at one anchor, the ensemble's forecast is put, authored ensemble:&lt;id&gt;, so its arrival is the latest of its members'; a member cleared takes it off with a sentence. Declaring an id again replaces it. Answers the ensemble.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    /// <param name="id">The ensemble's label, as a model's: [a-z0-9_]{1,32}, none of its members.</param>
    /// <param name="members">The members' model labels, at least two.</param>
    /// <param name="rule">mean, median or weighted.</param>
    /// <param name="bands">quantiles_averaged (each level's edges averaged; the band claims no p), members_pooled (the mixture's quantiles) or none. Omitted: quantiles_averaged.</param>
    /// <param name="weights">For weighted: one weight a member, in the members' order.</param>
    public Task<JsonNode?> EnsembleDefine(string bench, string symbol, string id, IReadOnlyList<string> members, string rule, string? bands = null, IReadOnlyList<double>? weights = null, CancellationToken ct = default) =>
        _c.Call("forecast_ensemble_define", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["id"] = id, ["members"] = members, ["rule"] = rule, ["bands"] = bands, ["weights"] = weights }, ct);

    /// <summary>
    /// Answers the ensembles declared on a workbench: each one's label, market, members, rules, the latest member arrival its forecast was made from, and what it last said where none stands.
    /// Scope: read. Since: 3.4.0.
    /// </summary>
    public Task<JsonNode?> EnsembleList(string bench, CancellationToken ct = default) =>
        _c.Call("forecast_ensemble_list", new Dictionary<string, object?> { ["bench"] = bench }, ct);

    /// <summary>
    /// Removes an ensemble from a workbench's market, and its forecast with it. Answers whether one was there.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    public Task<JsonNode?> EnsembleRemove(string bench, string symbol, string id, CancellationToken ct = default) =>
        _c.Call("forecast_ensemble_remove", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["id"] = id }, ct);

    /// <summary>
    /// Runs one evaluation run per cell over the workbench's own history, each with an ONNX model from the models folder asked INSIDE the loop by Bentrix's built-in engine: at each close the window its manifest describes is cut there, the model run, its output put as that close's forecast, stamped close + latency, and scored as forecast_eval_close scores. The workbench's clock does not move. Answers each cell's report, or why it did not run, in the cells' order.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    /// <param name="cells">One evaluation run each.</param>
    public Task<JsonNode?> EvalBatch(string bench, object cells, CancellationToken ct = default) =>
        _c.Call("forecast_eval_batch", new Dictionary<string, object?> { ["bench"] = bench, ["cells"] = cells }, ct);

    /// <summary>
    /// Ends an evaluation run: its report (forecast_report's measures over the run's forecasts against the workbench's history, each step only if it had not closed at its stamped arrival, the latency said) and its journal written as one JSON-lines file in the export folder under this agent's name. The bench's own journal is not touched.
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    public Task<JsonNode?> EvalClose(long eval, CancellationToken ct = default) =>
        _c.Call("forecast_eval_close", new Dictionary<string, object?> { ["eval"] = eval }, ct);

    /// <summary>
    /// Starts an evaluation run over the workbench's own history between from_ms and to_ms (its clock at most; the clock does not move): the closes of forecast_tf on the first market, one in stride. forecast_eval_next hands the window cut at each close and scores the forecast handed back for the close before; forecast_eval_close answers the report. Each forecast's arrival is stamped close + latency (none, measured - this model's mean live latency on the bench's journal, 0 and said when it has none - or N ms), and a step it could already see is late and unscored, exactly as live. Over a span the workbench's laboratory does not hold nothing is made or fetched: the answer is an ask - which laboratory, the span, the days and markets downloaded, what MetaTrader will be asked - and a watch uri, and the person answers on one sheet in Bentrix's window (Make it and run, or No); forecast_eval_state and the event bentrix://forecasts/eval say what came of it. Answers the eval's id, the closes and what it runs on.
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    /// <param name="bench">The workbench whose history the run walks; its clock does not move.</param>
    /// <param name="symbols">The markets of each window, the first the forecast's.</param>
    /// <param name="frames">The frames of each window: intervals' labels.</param>
    /// <param name="forecastTf">The interval whose closes the run walks, and the forecast's.</param>
    /// <param name="model">The model label the run's forecasts carry.</param>
    /// <param name="latency">The latency each forecast is stamped with: "none", "measured" (this model's mean live latency on the bench's journal, the default), or a number of ms.</param>
    /// <param name="limit">Closed bars per frame in each window (200 when omitted).</param>
    /// <param name="retrain">When a retrain is due: "session" (each new day), "week", or a count of closes.</param>
    /// <param name="runModel">**A model of the models folder Bentrix runs at each close itself**: the run is driven by Bentrix to its end, the model handed each window and its answer scored, its label the model's own; omitted, the caller drives the run with forecast_eval_next.</param>
    /// <param name="stride">One close in N.</param>
    /// <param name="toMs">At most the workbench's clock; omitted, the clock.</param>
    public Task<JsonNode?> EvalMake(string bench, IReadOnlyList<string> symbols, IReadOnlyList<string> frames, string forecastTf, long fromMs, string model, object? latency = null, long? limit = null, string? retrain = null, string? runModel = null, long? stride = null, long? toMs = null, CancellationToken ct = default) =>
        _c.Call("forecast_eval_make", new Dictionary<string, object?> { ["bench"] = bench, ["symbols"] = symbols, ["frames"] = frames, ["forecast_tf"] = forecastTf, ["from_ms"] = fromMs, ["model"] = model, ["latency"] = latency, ["limit"] = limit, ["retrain"] = retrain, ["run_model"] = runModel, ["stride"] = stride, ["to_ms"] = toMs }, ct);

    /// <summary>
    /// Scores the forecast handed for the last window - checked as forecast_put checks it, its arrival stamped at that window's close plus the run's latency - and hands the window cut at the next close: close_ms, the window (bars_window's answer at that instant, nothing later), done once the closes are walked, scored (the forecasts recorded so far), and retrain_due where the run's retrain rule falls.
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    /// <param name="forecast">The forecast for the window handed last, as forecast_spec (its model and market the run's; its anchor the last closed bar of that window's close). Omitted for the first window, or to pass a close.</param>
    public Task<JsonNode?> EvalNext(long eval, object? forecast = null, CancellationToken ct = default) =>
        _c.Call("forecast_eval_next", new Dictionary<string, object?> { ["eval"] = eval, ["forecast"] = forecast }, ct);

    /// <summary>
    /// A run's closes walked and left, its forecasts recorded, its latency rule and retrain rule; or where an ask forecast_eval_make answered stands: asked (the sheet stands in Bentrix's window), confirmed (Make it and run pressed), made_laboratory (the workbench over the span is made and its days are downloading), started (with the eval to drive), declined (by the person - never a failure), or failed (with why). The person's press on the sheet is the one answer; no tool answers it. The event bentrix://forecasts/eval carries each move of an ask.
    /// Scope: read. Since: 3.3.0.
    /// </summary>
    /// <param name="ask">Or an ask it answered (bentrix://ask/N), over days the workbench's laboratory did not hold.</param>
    /// <param name="eval">A run forecast_eval_make started.</param>
    public Task<JsonNode?> EvalState(string? ask = null, long? eval = null, CancellationToken ct = default) =>
        _c.Call("forecast_eval_state", new Dictionary<string, object?> { ["ask"] = ask, ["eval"] = eval }, ct);

    /// <summary>
    /// Answers the forecasts a reader at at_ms (the workbench's clock when omitted) sees on the workbench, by arrival - never one that arrived after that instant - each with its model, market, epoch, form, anchor, put_ms, steps' count, state (current, partly realized, realized), how many steps have closed, who put it and its colours; steps true hands the steps. arrivals lists every arrival the workbench keeps per model.
    /// Scope: read. Since: 3.3.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="atMs">The instant to read at, UTC ms: what a reader at that instant saw. Omitted, the workbench's clock.</param>
    /// <param name="model">One model; omitted, every model.</param>
    /// <param name="steps">true hands each forecast's steps too.</param>
    /// <param name="symbol">One market; omitted, every market.</param>
    public Task<JsonNode?> Get(string bench, long? atMs = null, string? model = null, bool? steps = null, string? symbol = null, CancellationToken ct = default) =>
        _c.Call("forecast_get", new Dictionary<string, object?> { ["bench"] = bench, ["at_ms"] = atMs, ["model"] = model, ["steps"] = steps, ["symbol"] = symbol }, ct);

    /// <summary>
    /// Applies a preset's look to a chart, or with all true to every chart of that chart's workbench, as the card's Preset row does; each chart keeps its Show and the models its legend hid. Answers the charts it was applied to.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    /// <param name="name">The preset: bentrix, quiet, or a name it was saved under.</param>
    /// <param name="chart">The chart it is applied to; omitted with all true, every chart of the workbench the chart is on.</param>
    public Task<JsonNode?> PresetApply(string name, string chart, bool? all = null, CancellationToken ct = default) =>
        _c.Call("forecast_preset_apply", new Dictionary<string, object?> { ["name"] = name, ["chart"] = chart, ["all"] = all }, ct);

    /// <summary>
    /// Deletes a preset the person saved; Bentrix's own (bentrix, quiet) cannot be. Answers every preset's name left.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    public Task<JsonNode?> PresetDelete(string name, CancellationToken ct = default) =>
        _c.Call("forecast_preset_delete", new Dictionary<string, object?> { ["name"] = name }, ct);

    /// <summary>
    /// Saves a chart's forecast look - every row of its Forecast tab but Show and the models its legend hid - under a name, kept on this machine; the card's Preset row offers it beside Bentrix's own presets (bentrix, quiet). Saving a name again replaces it. Answers every preset's name.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    /// <param name="chart">The chart whose look is saved.</param>
    /// <param name="name">The preset's name, [a-z0-9_]{1,32}, not a built-in's (bentrix, quiet).</param>
    public Task<JsonNode?> PresetSave(string chart, string name, CancellationToken ct = default) =>
        _c.Call("forecast_preset_save", new Dictionary<string, object?> { ["chart"] = chart, ["name"] = name }, ct);

    /// <summary>
    /// Hands over a forecast_spec: drawn on every chart of its market on the workbench from the instant it arrives, which Bentrix stamps as put_ms on the workbench's own clock (a laboratory's replay instant, a live bench's market clock) - no reader sees it before. Refused by name where it cannot be true (a high under its body, a band upside down, falling quantiles, an anchor that is not a closed bar of the form's interval, an element form naming an interval) with what is offered instead; a lower epoch than the model's standing forecast is refused; past Models per market the answer names the setting. Answers the arrival, the state, where the steps end, the replaced epoch, and each chart of the market with where the forecast stands on it.
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="forecast">The forecast, as forecast_spec describes it.</param>
    /// <param name="stepsTotal">**A long forecast in chunks**: the steps the whole forecast will hold. Its steps here are the first chunk; the rest come by forecast_put_chunk, and it arrives - for every reader - when the last one lands.</param>
    public Task<JsonNode?> Put(string bench, object forecast, long? stepsTotal = null, CancellationToken ct = default) =>
        _c.Call("forecast_put", new Dictionary<string, object?> { ["bench"] = bench, ["forecast"] = forecast, ["steps_total"] = stepsTotal }, ct);

    /// <summary>
    /// Appends steps to a forecast opened with forecast_put and steps_total, from_step being the count already sent. Until the last chunk lands the forecast exists for no reader (the legend says receiving N of M); at the last one the whole forecast is checked as forecast_put checks it and arrives then, stamped put_ms. A chunk out of order, of another epoch or past the total is refused by name. Answers have and of, and at the last chunk forecast_put's answer.
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="epoch">The epoch the forecast was opened with.</param>
    /// <param name="fromStep">The index (0-based) of this chunk's first step: the count of steps already sent.</param>
    /// <param name="steps">The steps, as forecast_spec's steps.</param>
    public Task<JsonNode?> PutChunk(string bench, string symbol, string model, long epoch, long fromStep, object steps, CancellationToken ct = default) =>
        _c.Call("forecast_put_chunk", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["model"] = model, ["epoch"] = epoch, ["from_step"] = fromStep, ["steps"] = steps }, ct);

    /// <summary>
    /// Hands over up to 256 forecast_specs to one workbench in one call, every one arriving at the same instant of its clock: several markets and several models. Each refused one is named by its index with why; all_or_nothing lands none when one is refused. Answers put (each landed forecast as forecast_put answers it) and refused [{index, why}].
    /// Scope: lab. Since: 3.3.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="forecasts">The forecasts, each a forecast_spec: several markets, several models, at most 256.</param>
    /// <param name="allOrNothing">true lands none when one is refused; false (the default) lands every one that can be, and names the rest.</param>
    public Task<JsonNode?> PutMany(string bench, object forecasts, bool? allOrNothing = null, CancellationToken ct = default) =>
        _c.Call("forecast_put_many", new Dictionary<string, object?> { ["bench"] = bench, ["forecasts"] = forecasts, ["all_or_nothing"] = allOrNothing }, ct);

    /// <summary>
    /// Scores a model's journalled forecasts on one market against the bars the workbench's history holds, up to its clock - each step only if it had not closed when its forecast arrived: per step and overall, the count, the close's mean absolute error, its percentage, the root mean square error, the mean signed error, the direction hit rate (the close's move from the anchor's own close), each band's coverage against its nominal p, the quantiles' pinball loss, the samples' CRPS, and the mean latency (put_ms after the anchor's close). Steps still to close are pending; steps a late arrival could already see are late and unscored.
    /// Scope: read. Since: 3.3.0.
    /// </summary>
    /// <param name="last">Only the newest N forecasts.</param>
    /// <param name="sinceMs">Only forecasts that arrived at or after this instant, UTC ms.</param>
    /// <param name="source">live or eval; omitted, both.</param>
    public Task<JsonNode?> Report(string bench, string symbol, string model, long? last = null, long? sinceMs = null, string? source = null, CancellationToken ct = default) =>
        _c.Call("forecast_report", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["model"] = model, ["last"] = last, ["since_ms"] = sinceMs, ["source"] = source }, ct);

    /// <summary>
    /// The forecasts a reader at the workbench's clock sees, by arrival, each with its model, market, epoch, anchor, put_ms, steps, state and author; and every arrival kept per model.
    /// Scope: read. Since: 3.3.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/forecasts
    /// </summary>
    /// <param name="home">`lab` or `account`.</param>
    /// <param name="owner">The laboratory's or the account's id.</param>
    public Task<JsonNode?> Models(string home, string owner, string bench, CancellationToken ct = default) =>
        _c.ReadResource("bentrix://{home}/{owner}/bench/{bench}/forecasts", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench }, ct);

    /// <summary>
    /// Each move of an ask forecast_eval_make answered, oldest first: ask, state (asked, confirmed, made_laboratory, started, declined, failed), eval once started, laboratory once made, by: "the person" on a decline, why on a failure, at_ms. next is the count of items read.
    /// Scope: read. Since: 3.5.0.
    /// URI: bentrix://forecasts/eval{?after}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> ForecastsEval(string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://forecasts/eval{?after}", null, after, timeoutMs, ct);

    /// <summary>
    /// Every forecast as it arrived on the workbench, oldest first, at most 500 a page: market, model, epoch, author, interval, anchor_ms, anchor_close_ms, the anchor bar's own close, put_ms (the arrival on the bench's clock), each step's open and close and the steps as given, and its source (live, or an evaluation run's). Written to a file under the workspace and read back after a restart. model and symbol filter it; next is the count of lines read.
    /// Scope: read. Since: 3.3.0.
    /// URI: bentrix://{home}/{owner}/bench/{bench}/forecasts/journal{?after,model,symbol}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> ForecastsJournal(string home, string owner, string bench, string? model = null, string? symbol = null, string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://{home}/{owner}/bench/{bench}/forecasts/journal{?after,model,symbol}", new Dictionary<string, object?> { ["home"] = home, ["owner"] = owner, ["bench"] = bench, ["model"] = model, ["symbol"] = symbol }, after, timeoutMs, ct);
}

public sealed class IndicatorApi
{
    private readonly Client _c;

    internal IndicatorApi(Client c) => _c = c;

    /// <summary>
    /// The board of the script in front: where each statement's cluster stands, laid out by hand, kept beside the script in the indicators folder and never in its text. read answers it; place moves one statement's cluster; tidy lays them all again in the text's order; forget deletes the arrangement. A view act, as a person's drag of a cluster's body is: no byte of the script changes. The script must be saved into the indicators folder.
    /// Scope: lab. Since: 3.14.0.
    /// </summary>
    /// <param name="action">`read` answers the arrangement; `place` puts statement `index` (from 0, in the text's order) at `x`, `y`; `tidy` lays every statement again in the text's order; `forget` deletes the arrangement.</param>
    public Task<JsonNode?> IdeBoard(string action, long? index = null, double? x = null, double? y = null, CancellationToken ct = default) =>
        _c.Call("ide_board", new Dictionary<string, object?> { ["action"] = action, ["index"] = index, ["x"] = x, ["y"] = y }, ct);

    /// <summary>
    /// Sets the whole text of the tab in front of the Assay IDE, as typing does: checked at once, one entry the person's Ctrl+Z takes back, nothing saved (indicator_install saves). Answers the IDE as ide_state does, with the new findings.
    /// Scope: lab. Since: 1.16.0.
    /// </summary>
    /// <param name="source">The whole new text of the tab in front.</param>
    public Task<JsonNode?> IdeEdit(string source, CancellationToken ct = default) =>
        _c.Call("ide_edit", new Dictionary<string, object?> { ["source"] = source }, ct);

    /// <summary>
    /// Answers the sheet of the tab in front of the Assay IDE: a row per statement with its own line number and the kind of thing it is, and inside each row the nodes it draws, each with its kind, its label and the lines its text stands on. The same sheet the window draws, read the same way a person reads it. Writes nothing.
    /// Scope: read. Since: 3.14.0.
    /// </summary>
    public Task<JsonNode?> IdeGraph(CancellationToken ct = default) =>
        _c.Call("ide_graph", null, ct);

    /// <summary>
    /// Makes one gesture on the sheet of the tab in front, exactly as a person's press or drag makes it: written into the text by the same function, one entry the person's Ctrl+Z takes back, checked as typing is, nothing saved. A gesture the sheet refuses is answered with its sentence and changes nothing. Answers the IDE as ide_state does.
    /// Scope: lab. Since: 3.14.0.
    /// </summary>
    /// <param name="gesture">One gesture of the sheet, as `ide_graph`'s rows and nodes name the text: `{"SetLiteral": {"at": span, "value": "20"}}`, `{"Wire": {"from": span, "to": span, "cast": null}}`, `{"AddRow": {"after": span, "text": "…"}}`, `{"MoveRow": …}`, `{"DeleteRow": …}`, `{"WrapIn": {"first": span, "last": span, "with": "If"}}`, `{"Extract": …}` and the rest; a span is `{"start": {"line": l, "col": c}, "end": {…}}` exactly as `ide_graph` answers it.</param>
    public Task<JsonNode?> IdeGraphEdit(object gesture, CancellationToken ct = default) =>
        _c.Call("ide_graph_edit", new Dictionary<string, object?> { ["gesture"] = gesture }, ct);

    /// <summary>
    /// Opens the Assay IDE on a script of the indicators folder by its file name, brought to the front if a tab holds it already, or on a new script's text in a new tab, not saved. Answers the IDE as ide_state does.
    /// Scope: lab. Since: 1.16.0.
    /// </summary>
    /// <param name="file">A script of the indicators folder by its file name (`mean.assay`), brought to the front if a tab holds it already. Give this or `source`.</param>
    /// <param name="source">Or a new script's whole text, in a new tab, not saved.</param>
    public Task<JsonNode?> IdeOpen(string? file = null, string? source = null, CancellationToken ct = default) =>
        _c.Call("ide_open", new Dictionary<string, object?> { ["file"] = file, ["source"] = source }, ct);

    /// <summary>
    /// Answers whether the Assay IDE is open, its tabs (each tab's number, name, whether it is unsaved and whether it is in front, and the tab shown beside it in a split), and the tab in front: its name, file, text, findings and stops with their conditions. Writes nothing.
    /// Scope: read. Since: 1.16.0.
    /// </summary>
    public Task<JsonNode?> IdeState(CancellationToken ct = default) =>
        _c.Call("ide_state", null, ct);

    /// <summary>
    /// Puts a stop on a line of the script in front of the Assay IDE, with the condition it stops on, or takes it away, as F9 and the stop's condition field do. A run and inspect then says where it fires. Answers the IDE as ide_state does.
    /// Scope: lab. Since: 1.16.0.
    /// </summary>
    /// <param name="line">The line of the script in front, from 1.</param>
    /// <param name="on">True puts a stop there (or changes its condition), false takes it away.</param>
    /// <param name="condition">The condition it stops on, an expression of the script (`n % 2 == 1`); empty or absent: whenever the line runs.</param>
    public Task<JsonNode?> IdeStop(long line, bool on, string? condition = null, CancellationToken ct = default) =>
        _c.Call("ide_stop", new Dictionary<string, object?> { ["line"] = line, ["on"] = on, ["condition"] = condition }, ct);

    /// <summary>
    /// Writes a study script into the person's indicators folder: a Python study, or an Assay script when the file name ends .assay. A file already there is written over only with replace, and then waits for the person's tick like a new one. It is not run - not even read for its declaration - until the person ticks it in Settings › Indicators. Answers the file and its state.
    /// Scope: admin. Since: 1.2.0.
    /// </summary>
    /// <param name="fileName">The script's file name in the indicators folder: [a-z0-9_]{1,32}, with or without .py; with .assay for an Assay script.</param>
    /// <param name="source">The script's whole text: one @study, as bentrix.study declares it; or an Assay script, which script_check checks first.</param>
    /// <param name="replace">true writes over the script already in the folder under this name (the Assay editor's Save); the file is then the agent's and waits for the person's tick again. Omitted or false, a file already there is never written over.</param>
    public Task<JsonNode?> Install(string fileName, string source, bool? replace = null, CancellationToken ct = default) =>
        _c.Call("indicator_install", new Dictionary<string, object?> { ["file_name"] = fileName, ["source"] = source, ["replace"] = replace }, ct);

    /// <summary>
    /// Answers the text of one script in the person's indicators folder - an Assay script or a Python study - with its state as indicators_state lists it: what the Assay editor opens. Only a file of that folder is read; a script from elsewhere is handed to script_check and indicator_install as text.
    /// Scope: read. Since: 1.10.0.
    /// </summary>
    /// <param name="file">The script's file name in the indicators folder, with its extension: my_rsi.assay or my_sma.py.</param>
    public Task<JsonNode?> Read(string file, CancellationToken ct = default) =>
        _c.Call("indicator_read", new Dictionary<string, object?> { ["file"] = file }, ct);

    /// <summary>
    /// Reads the person's indicators folder again, as Settings › Indicators' Rescan does: each script that may run describes itself, and indicators_state reads the outcome once it lands.
