        _c.Call("lab_create", new Dictionary<string, object?> { ["currency"] = currency, ["leverage"] = leverage, ["margin_mode"] = marginMode, ["name"] = name, ["opening_balance"] = openingBalance, ["source"] = source, ["time_zone"] = timeZone }, ct);

