        _c.CallJob("lab_delete", new Dictionary<string, object?> { ["lab"] = lab }, ct);

    /// <summary>
    /// Restore puts an orphan whose recording has no laboratory back on the list, as its row's restore does, at once. Move (its workbenches into the laboratory its recording already has) and remove (its workbenches lost) ask the person on its row; answers a job for those.
