    /// <summary>
    /// Pauses a running model (it is asked nothing at the closes while paused; its last forecast stays) or resumes it (paused false), as the legend row's Pause does. Answers its state.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    /// <param name="paused">For model_pause: true pauses, false resumes.</param>
    public Task<JsonNode?> Pause(long model, bool? paused = null, CancellationToken ct = default) =>
        _c.Call("model_pause", new Dictionary<string, object?> { ["model"] = model, ["paused"] = paused }, ct);

    /// <summary>
    /// Runs a model of the models folder once - consent checked, on the engine the person chose, in a process of its own unless the person keeps the built-in engine inside Bentrix - on the window cut at the last close of its interval at or before at_ms (the workbench's clock when omitted), and puts what it answers as its forecast - or, for a model whose manifest declares outputs (schema 2), each output as output_put puts it - authored model:&lt;name&gt;, stamped with the workbench's clock when it lands. The frame waits for it at most the Time cap per run. Answers the forecast's state (or the outputs put), the anchor, how long the model took and whether that was late.
    /// Scope: lab. Since: 3.6.0.
    /// </summary>
    /// <param name="name">A model's name in the models folder.</param>
    /// <param name="symbol">The market it forecasts, one of the workbench's.</param>
    /// <param name="atMs">A moment at or before the workbench's clock: the model runs at the last close of its interval by then. Omitted, the clock.</param>
    public Task<JsonNode?> RunOnce(string name, string bench, string symbol, long? atMs = null, CancellationToken ct = default) =>
        _c.Call("model_run_once", new Dictionary<string, object?> { ["name"] = name, ["bench"] = bench, ["symbol"] = symbol, ["at_ms"] = atMs }, ct);

    /// <summary>
    /// Starts a model from the person's models folder - a Python file declaring one @bentrix.model, run by the person's own interpreter, or an ONNX model's folder (model_manifest), run by Bentrix's built-in engine - in a process of its own, on a workbench's market: at each close of its interval it is handed the window cut there, and what it answers is put on the chart as its forecast, stamped with the instant it came back (a slow model's forecast arrives late, as a live program's does). Only a file in the models folder starts; its process carries no Bentrix variable. Answers the model's id and state.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    /// <param name="bench">The workbench whose closes the model runs at.</param>
    /// <param name="symbol">The market it forecasts, one of the workbench's.</param>
    /// <param name="file">A name in the models folder: a .py declaring one @bentrix.model, or an ONNX model's folder (model.onnx beside its manifest.json, model_manifest).</param>
    public Task<JsonNode?> Start(string bench, string symbol, string file, CancellationToken ct = default) =>
        _c.Call("model_start", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["file"] = file }, ct);

    /// <summary>
    /// Ends a model's process; its forecasts already put stay on the workbench until cleared.
    /// Scope: lab. Since: 3.4.0.
    /// </summary>
    /// <param name="paused">For model_pause: true pauses, false resumes.</param>
    public Task<JsonNode?> Stop(long model, bool? paused = null, CancellationToken ct = default) =>
        _c.Call("model_stop", new Dictionary<string, object?> { ["model"] = model, ["paused"] = paused }, ct);

    /// <summary>
    /// A running model as model_start answered it: its file, workbench, market, state and why it ended, its declaration, its runs, its late answers, its last error and its engine.
    /// Scope: read. Since: 3.6.0.
    /// URI: bentrix://model/{model}
    /// </summary>
    /// <param name="model">A running model's id, as model_start answered it.</param>
    public Task<JsonNode?> State(string model, CancellationToken ct = default) =>
        _c.ReadResource("bentrix://model/{model}", new Dictionary<string, object?> { ["model"] = model }, ct);

    /// <summary>
    /// Every model Bentrix is running: its file, workbench, market, state (starting, running, paused, ended and why), what it declared, how many closes it answered, how many past the time cap, and its last error; and the models folder with its .py files.
    /// Scope: read. Since: 3.4.0.
    /// URI: bentrix://models
    /// </summary>
    public Task<JsonNode?> ModelsState(CancellationToken ct = default) =>
        _c.ReadResource("bentrix://models", null, ct);

    /// <summary>
    /// Each run of a model Bentrix runs, oldest first - a running model's close, model_run_once, an evaluation it drives, a strategy reading it: model (its label), anchor_ms, took_ms, late (past Late is), error, at_ms. next is the count of items read.
    /// Scope: read. Since: 3.6.0.
    /// URI: bentrix://models/runs{?after}
    /// after: the cursor to read since; null yields only what is new. timeoutMs: how long one wait lasts before it asks again.
    /// </summary>
    public IAsyncEnumerable<JsonNode?> ModelsRuns(string? after = null, int timeoutMs = 30000, CancellationToken ct = default) =>
        _c.Watch("bentrix://models/runs{?after}", null, after, timeoutMs, ct);
}

public sealed class OutputApi
{
    private readonly Client _c;

    internal OutputApi(Client c) => _c = c;

    /// <summary>
    /// Shows or hides one model's output on one chart, as its legend row's eye does - a hidden one keeps its row, dim - and turns the chart's Zones on or off (each output pane shaded beyond its thresholds). A field not named keeps its value. Answers the chart's hidden outputs and its Zones.
    /// Scope: lab. Since: 3.9.0.
    /// </summary>
    /// <param name="chart">The chart's uri.</param>
    /// <param name="shown">Draw this output on this chart (the legend's eye).</param>
    /// <param name="zones">The chart's Zones: every output pane shaded above its upper threshold and below its lower one.</param>
    public Task<JsonNode?> ChartSetOutput(string chart, string model, string output, bool? shown = null, bool? zones = null, CancellationToken ct = default) =>
        _c.Call("chart_set_output", new Dictionary<string, object?> { ["chart"] = chart, ["model"] = model, ["output"] = output, ["shown"] = shown, ["zones"] = zones }, ct);

    /// <summary>
    /// Hands over the realised values Bentrix cannot compute itself, for one output on one market: each {anchor_ms, and exactly one of value (a rank's residual target, a series line's realised number), label (the class by the person's own labelling rule) or event (whether the event came)}. Paired with the output's value of the same anchor in output_report; a later put of the same anchor replaces it. Refused by name: an anchor past the workbench's clock (it is the future), a document carrying two realised things in one row or none, names not [a-z0-9_]{1,32}.
    /// Scope: lab. Since: 3.10.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="actuals">The output_actuals document: schema_version 1, model, output, symbol, and actuals [{anchor_ms, value | label | event}] - one realised thing each.</param>
    public Task<JsonNode?> ActualPut(string bench, object actuals, CancellationToken ct = default) =>
        _c.Call("output_actual_put", new Dictionary<string, object?> { ["bench"] = bench, ["actuals"] = actuals }, ct);

    /// <summary>
    /// Removes the outputs of one market, model or output name, or all of them, from the workbench, every arrival kept for them included, as the x on an output's legend row does. The person's meanings stay. A path output is removed by forecast_clear. Answers how many arrivals went.
    /// Scope: lab. Since: 3.9.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="model">One model; omitted, every model.</param>
    /// <param name="output">One output; omitted, every output.</param>
    /// <param name="symbol">One market; omitted, every market.</param>
    public Task<JsonNode?> Clear(string bench, string? model = null, string? output = null, string? symbol = null, CancellationToken ct = default) =>
        _c.Call("output_clear", new Dictionary<string, object?> { ["bench"] = bench, ["model"] = model, ["output"] = output, ["symbol"] = symbol }, ct);

    /// <summary>
    /// output_report for several outputs on one market, a row each, over the same bars and actuals, by name - never ranked: a comparison is the laboratory's instrument and nothing here is published or ordered by a measure. An output that cannot be reported says why in its row.
    /// Scope: read. Since: 3.10.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="outputs">The outputs to compare, each "model.output"; omitted, every output the bench holds on the market.</param>
    public Task<JsonNode?> Compare(string bench, string symbol, string? interval = null, IReadOnlyList<string>? outputs = null, CancellationToken ct = default) =>
        _c.Call("output_compare", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["interval"] = interval, ["outputs"] = outputs }, ct);

    /// <summary>
    /// Answers the outputs a reader at at_ms (the workbench's clock when omitted) sees on the workbench, by arrival - never one that arrived after that instant, whatever its anchor - each with its model, output, market, kind, epoch, anchor, put_ms, values, range, who put it, and the meaning in force (the person's, else the model's suggestion). arrivals lists every arrival kept per output. A path output is read by forecast_get.
    /// Scope: read. Since: 3.9.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="atMs">The instant to read at, UTC ms: what a reader at that instant saw. Omitted, the workbench's clock.</param>
    /// <param name="model">One model; omitted, every model.</param>
    /// <param name="output">One output of the model; omitted, every output.</param>
    /// <param name="symbol">One market; omitted, every market.</param>
    public Task<JsonNode?> Get(string bench, long? atMs = null, string? model = null, string? output = null, string? symbol = null, CancellationToken ct = default) =>
        _c.Call("output_get", new Dictionary<string, object?> { ["bench"] = bench, ["at_ms"] = atMs, ["model"] = model, ["output"] = output, ["symbol"] = symbol }, ct);

    /// <summary>
    /// Answers the person's meaning of one model's output on one workbench and who set it (null where nobody has), the meaning the model suggests with its newest arrival, and the one in force: the person's, else the suggestion.
    /// Scope: read. Since: 3.9.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    public Task<JsonNode?> MeaningGet(string bench, string model, string output, CancellationToken ct = default) =>
        _c.Call("output_meaning_get", new Dictionary<string, object?> { ["bench"] = bench, ["model"] = model, ["output"] = output }, ct);

    /// <summary>
    /// Sets the meaning of one model's output on one workbench - what its high and low values mean, the thresholds it acts at, its classes' words - checked against the range the output answers (a threshold outside it is refused in words). The meaning is the person's setting and never touches the model's file; an agent's is marked with its pairing, which the person sees. Only on a workbench this agent writes on: a laboratory's with lab, a paper bench's with paper; a real account's meaning is the person's alone. Refused until an output of that name has arrived on the workbench. Answers the meaning and who set it.
    /// Scope: lab. Since: 3.9.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="meaning">The meaning, as output_meaning describes it.</param>
    public Task<JsonNode?> MeaningSet(string bench, string model, string output, object meaning, CancellationToken ct = default) =>
        _c.Call("output_meaning_set", new Dictionary<string, object?> { ["bench"] = bench, ["model"] = model, ["output"] = output, ["meaning"] = meaning }, ct);

    /// <summary>
    /// Hands over an output_spec of any kind: read by every chart, alert and tool from the instant it arrives, which Bentrix stamps as put_ms on the workbench's own clock - never from its anchor, so a late output is read late. A path output is today's forecast and lands through the forecast's own door (forecast_put's answer). Refused by name where it cannot be true: a value outside its declared range, an anchor past the workbench's clock, a market the workbench does not hold, a document naming its own arrival, an epoch lower than the one standing. Answers the arrival, the replaced epoch and each chart of the market with whether it draws it.
    /// Scope: lab. Since: 3.9.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="output">The output, as output_spec describes it.</param>
    public Task<JsonNode?> Put(string bench, object output, CancellationToken ct = default) =>
        _c.Call("output_put", new Dictionary<string, object?> { ["bench"] = bench, ["output"] = output }, ct);

    /// <summary>
    /// Hands over up to 256 output_specs to one workbench in one call, every one arriving at the same instant of its clock: several markets, models and outputs of any kinds. Each refused one is named by its index with why; all_or_nothing lands none when one is refused. Answers put (each landed output as output_put answers it) and refused [{index, why}].
    /// Scope: lab. Since: 3.9.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="outputs">The outputs, each an output_spec: several markets, models and outputs, at most 256.</param>
    /// <param name="allOrNothing">true lands none when one is refused; false (the default) lands every one that can be, and names the rest.</param>
    public Task<JsonNode?> PutMany(string bench, object outputs, bool? allOrNothing = null, CancellationToken ct = default) =>
        _c.Call("output_put_many", new Dictionary<string, object?> { ["bench"] = bench, ["outputs"] = outputs, ["all_or_nothing"] = allOrNothing }, ct);

    /// <summary>
    /// Scores one output of one model on one market by its kind's own measures, against the workbench's bars up to its clock and the actuals handed over with output_actual_put - each value only against a bar that had not closed when it arrived (late values are counted, never scored; pending ones wait). A probability (a scalar read as a direction, or units probability): AUC, Brier, log-loss, a ten-bin calibration curve and the confusion at the meaning's act_above (0.5 without one), the event being the move over the step in the meaning's high direction. Another number: MAE, RMSE, mean signed error, Pearson and Spearman against the move over the step. Classes: log-loss, accuracy and each class's confusion, against the supplied labels (or up/down by the move's sign for a model naming exactly those). Quantiles: pinball and coverage per level against the step's close. Event: AUC, Brier, log-loss and the confusion at tau against the supplied events. Levels: the share of trades whose target was met before the stop, read from the bars' highs and lows. Rank: the per-date IC against the supplied target and, apart and labelled raw, against the move over the horizon. Position, weights and action are measured in money only by a laboratory strategy run under the meaning; text is never evaluated. Nothing here is published or ranked anywhere else.
    /// Scope: read. Since: 3.10.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    /// <param name="interval">The interval the output's steps are bars of, where its horizon does not name one (M1, H1, D1 ...).</param>
    /// <param name="line">A series output: the line scored against the realised values supplied.</param>
    /// <param name="sinceMs">Only outputs that arrived at or after this instant, UTC ms.</param>
    public Task<JsonNode?> Report(string bench, string symbol, string model, string output, string? interval = null, string? line = null, long? sinceMs = null, CancellationToken ct = default) =>
        _c.Call("output_report", new Dictionary<string, object?> { ["bench"] = bench, ["symbol"] = symbol, ["model"] = model, ["output"] = output, ["interval"] = interval, ["line"] = line, ["since_ms"] = sinceMs }, ct);

    /// <summary>
    /// Every output the workbench holds, by market, model and output: its kind, how many arrivals are kept, the newest one's put_ms at the workbench's clock (null before the first arrived), the person's meaning and who set it, the model's suggested meaning, and whether a chart of this release draws its kind.
    /// Scope: read. Since: 3.9.0.
    /// </summary>
    /// <param name="bench">The workbench's uri.</param>
    public Task<JsonNode?> OutputsState(string bench, CancellationToken ct = default) =>
        _c.Call("outputs_state", new Dictionary<string, object?> { ["bench"] = bench }, ct);
}

public sealed class RecordingsApi
{
    private readonly Client _c;

    internal RecordingsApi(Client c) => _c = c;

    /// <summary>
    /// The data-quality report Market Watch's Data quality... shows for a laboratory workbench's market over the workbench's days, measured off the store's own files: digits and point, ticks per year, traded days, the first day with real ticks and the days modelled before it, holes with their days, spikes, the share of ticks with both sides, zero-spread ticks and stretches, duplicate and backward stamps, and whose data it is - each figure with what it counts. Beside the figures, for a gate of the caller's own: traded, every day the store holds candles for; modelled, the traded days with no tick file (replayed from candles, never from ticks); holes, each day of a tick file with hours graded missing and those UTC hours; and per_year, each year's ticks, traded days, days with a tick file, modelled days and days with a hole. It reads every tick, so the first call starts the measure and answers measuring: true; call again for the report.
