    public Task<JsonNode?> GeneratedBasketCreate(string laboratory, string? basket = null, long? factors = null, string? group = null, object? matrix = null, IReadOnlyList<string>? members = null, string? workbench = null, CancellationToken ct = default) =>
        _c.Call("generated_basket_create", new Dictionary<string, object?> { ["laboratory"] = laboratory, ["basket"] = basket, ["factors"] = factors, ["group"] = group, ["matrix"] = matrix, ["members"] = members, ["workbench"] = workbench }, ct);

    /// <summary>
    /// The correlation of kept generated markets: the one their loadings imply (the shared factors' products and the pairs'), and the one their generated minute closes realise over the days asked, at the minutes they all traded - generated for the measure and kept nowhere. The two differ by the drift, the regimes' coupling and chance, which is what a person sees.
