        _c.Call("generated_market_create", new Dictionary<string, object?> { ["laboratory"] = laboratory, ["name"] = name, ["preset"] = preset, ["recipe_text"] = recipeText, ["seed"] = seed, ["workbench"] = workbench }, ct);

    /// <summary>
