    public Task<JsonNode?> GeneratedPreview(long? days = null, string? preset = null, string? recipeText = null, CancellationToken ct = default) =>
        _c.Call("generated_preview", new Dictionary<string, object?> { ["days"] = days, ["preset"] = preset, ["recipe_text"] = recipeText }, ct);

    /// <summary>
    /// A recipe's text read into its settings, with its identity (the hash that is the market's) and the generator version it renders under; a text that does not read, or a recipe this build does not render, is refused in words.
