        _c.Call("study_attach", new Dictionary<string, object?> { ["chart"] = chart, ["kind"] = kind, ["convention"] = convention, ["inputs"] = inputs, ["on"] = on, ["timeframe"] = timeframe, ["wait_close"] = waitClose }, ct);

    /// <summary>
