        _c.Call("study_series_get", new Dictionary<string, object?> { ["chart"] = chart, ["study"] = study, ["limit"] = limit }, ct);

    /// <summary>
    /// Hands over a custom study's values, each at one of the bars it is computed on: the chart's bar opens; on a chart built by price, its elements (each by its candle's open and its ordinal, chart_elements_get) or, set to the candles, the candles' opens; with a timeframe of its own, that timeframe's bar opens, read back onto the chart under its wait_close. A time past the workbench's cursor, or one that is not such a bar, is refused by name; at most 5000 values a call. A put under another epoch replaces the series, and a study set to compute on other bars drops it; the values are drawn on the chart and never saved. Answers how many were accepted, the newest time held, and how many a move of the clock back had cut since the last put.
    /// Scope: lab. Since: 1.2.0.
