        _c.Call("study_series_put", new Dictionary<string, object?> { ["chart"] = chart, ["study"] = study, ["epoch"] = epoch, ["times"] = times, ["lines"] = lines, ["append"] = append, ["ordinals"] = ordinals }, ct);

