    /// </summary>
    /// <param name="kind">The custom kind, custom:&lt;id&gt;.</param>
    public Task<JsonNode?> Undefine(string kind, CancellationToken ct = default) =>
        _c.Call("study_undefine", new Dictionary<string, object?> { ["kind"] = kind }, ct);

    /// <summary>
    /// Computes a study over a laboratory workbench's bars as its chart reads them at the cursor — never a bar past the clock — and answers each line by what it is, with the newest values beside their candles' times. An Assay indicator of the indicators folder is computed too, with no chart: study as custom:&lt;id&gt;, its inputs given or its defaults, each line by its declared name.
