/// <summary>One Bentrix endpoint, every capability of its catalogue under client.&lt;Domain&gt;.</summary>
public sealed class BentrixClient : Client
{
    public AccountApi Account { get; }
    public AccountsApi Accounts { get; }
    public AgentApi Agent { get; }
    public AlertApi Alert { get; }
    public AlertsApi Alerts { get; }
    public BenchApi Bench { get; }
    public CatalogueApi Catalogue { get; }
    public ChartApi Chart { get; }
    public DataApi Data { get; }
    public DrawingApi Drawing { get; }
    public DriversApi Drivers { get; }
    public ForecastApi Forecast { get; }
    public IndicatorApi Indicator { get; }
    public LaboratoryApi Laboratory { get; }
    public MarketwatchApi Marketwatch { get; }
    public ModelApi Model { get; }
    public OutputApi Output { get; }
    public RecordingsApi Recordings { get; }
    public ReplayApi Replay { get; }
    public RoomApi Room { get; }
    public SettingsApi Settings { get; }
    public StrategyApi Strategy { get; }
    public StudyApi Study { get; }
    public TemplateApi Template { get; }
    public TradeApi Trade { get; }
    public TradingApi Trading { get; }
    public WorkbenchApi Workbench { get; }
    public WorkspaceApi Workspace { get; }
    public ZoneApi Zone { get; }

    public BentrixClient(string url, string token, TimeSpan? timeout = null) : base(url, token, global::Bentrix.Mcp.GeneratedCatalogue.Version, timeout)
    {
        Account = new AccountApi(this);
        Accounts = new AccountsApi(this);
        Agent = new AgentApi(this);
        Alert = new AlertApi(this);
        Alerts = new AlertsApi(this);
        Bench = new BenchApi(this);
        Catalogue = new CatalogueApi(this);
        Chart = new ChartApi(this);
        Data = new DataApi(this);
        Drawing = new DrawingApi(this);
        Drivers = new DriversApi(this);
        Forecast = new ForecastApi(this);
        Indicator = new IndicatorApi(this);
        Laboratory = new LaboratoryApi(this);
        Marketwatch = new MarketwatchApi(this);
        Model = new ModelApi(this);
        Output = new OutputApi(this);
        Recordings = new RecordingsApi(this);
        Replay = new ReplayApi(this);
        Room = new RoomApi(this);
        Settings = new SettingsApi(this);
        Strategy = new StrategyApi(this);
        Study = new StudyApi(this);
        Template = new TemplateApi(this);
        Trade = new TradeApi(this);
        Trading = new TradingApi(this);
        Workbench = new WorkbenchApi(this);
        Workspace = new WorkspaceApi(this);
        Zone = new ZoneApi(this);
    }

    /// <summary>Find the running application through its agents folder, pair under <paramref name="name"/>, connect.</summary>
    public static async Task<BentrixClient> ConnectAsync(string? name = null, string? agentsFolder = null, CancellationToken ct = default)
    {
        var (url, token) = await Discovery.DiscoverAsync(agentsFolder, name, ct);
        return new BentrixClient(url, token);
    }
}
